-- Public Events catalog and individual bookings. Depends on 20261024160000.
insert into public.event_types(slug,name_sw,name_en,description_sw,description_en,display_order)
values('individual-booking','Booking ya kifaa au huduma moja','Individual equipment or service booking','Njia ya kukodisha kifaa au huduma moja bila package ya tukio.','Rent one item or service without building an event package.',999)
on conflict(slug) do nothing;

alter table public.event_equipment_items add column if not exists specifications jsonb not null default '{}'::jsonb;
alter table public.event_equipment_items add column if not exists security_deposit_tzs numeric(14,2) check(security_deposit_tzs is null or security_deposit_tzs>=0);
alter table public.event_equipment_items add column if not exists damage_rules text;
alter table public.event_equipment_items add column if not exists cancellation_policy text;
alter table public.event_equipment_items add column if not exists public_location_label text;
alter table public.event_equipment_items add column if not exists publication_status text not null default 'draft' check(publication_status in('draft','published','paused','rejected','suspended'));
alter table public.event_service_offerings add column if not exists travel_configuration jsonb not null default '{}'::jsonb;
alter table public.event_service_offerings add column if not exists included_equipment text;
alter table public.event_service_offerings add column if not exists cancellation_policy text;
alter table public.event_service_offerings add column if not exists publication_status text not null default 'draft' check(publication_status in('draft','published','paused','rejected','suspended'));

drop policy if exists event_equipment_public on public.event_equipment_items;
create policy event_equipment_public on public.event_equipment_items for select using(verification_status='verified' and publication_status='published' and is_active);
drop policy if exists event_offerings_public on public.event_service_offerings;
create policy event_offerings_public on public.event_service_offerings for select using(is_active and publication_status='published' and exists(select 1 from public.event_service_profiles p where p.id=provider_id and p.verification_status='verified' and p.is_active));

create table public.event_individual_bookings(
 id uuid primary key default gen_random_uuid(),reference text not null unique default('EIB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),
 customer_id uuid not null references public.profiles(id),plan_id uuid not null unique references public.event_plans(id),plan_item_id uuid not null unique references public.event_plan_items(id),
 booking_kind text not null check(booking_kind in('equipment','service')),requested_period tstzrange not null,requested_quantity integer,
 quoted_amount_tzs numeric(14,2) check(quoted_amount_tzs is null or quoted_amount_tzs>=0),pricing_mode text not null check(pricing_mode in('fixed','custom_quote')),
 status text not null default 'requested' check(status in('requested','provider_approved','provider_declined','quote_sent','quote_accepted','agreement_sent','confirmed','completed','cancelled','expired','disputed')),
 payment_status text not null default 'not_enabled' check(payment_status in('not_enabled','offline_arrangement','pending','paid','refundable','refunded','disputed')),
 customer_message text,provider_response text,provider_responded_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 check(not isempty(requested_period)),check((booking_kind='equipment' and requested_quantity is not null and requested_quantity>0)or(booking_kind='service' and requested_quantity is null))
);
create index event_individual_customer_idx on public.event_individual_bookings(customer_id,created_at desc);
create index event_individual_status_idx on public.event_individual_bookings(status,created_at desc);
create index event_equipment_catalog_idx on public.event_equipment_items(category_id,location_id,price_amount_tzs) where(verification_status='verified' and publication_status='published' and is_active);
create index event_offering_catalog_idx on public.event_service_offerings(provider_id,price_amount_tzs) where(publication_status='published' and is_active);
alter table public.event_individual_bookings enable row level security;
create policy individual_booking_participants on public.event_individual_bookings for select to authenticated using(customer_id=auth.uid() or public.is_admin() or exists(select 1 from public.event_plan_items i left join public.event_equipment_items e on e.id=i.equipment_id left join public.event_service_offerings o on o.id=i.offering_id left join public.event_service_profiles s on s.id=o.provider_id where i.id=plan_item_id and(e.owner_id=public.current_owner_id() or s.profile_id=auth.uid())));
create policy individual_booking_coordinator on public.event_individual_bookings for all to authenticated using(public.has_admin_permission('events.manage')) with check(public.has_admin_permission('events.manage'));

create or replace function public.search_public_event_equipment(p_search text default null,p_category_id uuid default null,p_location_id uuid default null,p_start_at timestamptz default null,p_end_at timestamptz default null,p_min_price numeric default null,p_max_price numeric default null,p_sort text default 'recommended',p_limit integer default 20,p_offset integer default 0)
returns table(id uuid,name text,description text,category_id uuid,category_name_sw text,category_name_en text,public_location_label text,price_amount_tzs numeric,price_unit text,total_quantity integer,available_quantity integer,media_paths jsonb,setup_minutes integer,return_buffer_minutes integer,security_deposit_tzs numeric) language sql stable security definer set search_path=public as $$
 select e.id,e.name,e.description,e.category_id,c.name_sw,c.name_en,e.public_location_label,e.price_amount_tzs,e.price_unit,e.total_quantity,
 greatest(0,e.total_quantity-coalesce((select sum(a.quantity)::integer from public.event_equipment_allocations a where a.equipment_id=e.id and a.status in('held','confirmed') and(p_start_at is null or p_end_at is null or a.occupied_period&&tstzrange(p_start_at-make_interval(mins=>e.setup_minutes),p_end_at+make_interval(mins=>e.return_buffer_minutes),'[)'))and(a.expires_at is null or a.expires_at>now())),0))::integer,e.media_paths,e.setup_minutes,e.return_buffer_minutes,e.security_deposit_tzs
 from public.event_equipment_items e join public.event_equipment_categories c on c.id=e.category_id
 where e.verification_status='verified' and e.publication_status='published' and e.is_active and(p_category_id is null or e.category_id=p_category_id)and(p_location_id is null or e.location_id=p_location_id)and(p_min_price is null or e.price_amount_tzs>=p_min_price)and(p_max_price is null or e.price_amount_tzs<=p_max_price)and(nullif(trim(p_search),'') is null or to_tsvector('simple',coalesce(e.name,'')||' '||coalesce(e.description,''))@@plainto_tsquery('simple',trim(p_search)))
 order by case when p_sort='price_low' then e.price_amount_tzs end asc,case when p_sort='price_high' then e.price_amount_tzs end desc,case when p_sort='newest' then e.created_at end desc,e.created_at desc limit least(greatest(p_limit,1),50) offset greatest(p_offset,0)
$$;

create or replace function public.search_public_event_services(p_search text default null,p_provider_kind text default null,p_location_id uuid default null,p_start_at timestamptz default null,p_end_at timestamptz default null,p_min_price numeric default null,p_max_price numeric default null,p_sort text default 'recommended',p_limit integer default 20,p_offset integer default 0)
returns table(offering_id uuid,provider_id uuid,title text,description text,display_name text,provider_kind text,biography text,experience_years integer,pricing_mode text,price_amount_tzs numeric,duration_minutes integer,portfolio_media jsonb,is_available boolean) language sql stable security definer set search_path=public as $$
 select o.id,p.id,o.title,o.description,p.display_name,p.provider_kind,p.biography,p.experience_years,o.pricing_mode,o.price_amount_tzs,o.duration_minutes,p.portfolio_media,
 not exists(select 1 from public.event_provider_unavailability u where u.provider_id=p.id and p_start_at is not null and p_end_at is not null and u.unavailable_period&&tstzrange(p_start_at,p_end_at,'[)'))and not exists(select 1 from public.event_service_bookings b where b.provider_id=p.id and b.status in('held','confirmed')and p_start_at is not null and p_end_at is not null and b.service_period&&tstzrange(p_start_at,p_end_at,'[)')and(b.expires_at is null or b.expires_at>now()))
 from public.event_service_offerings o join public.event_service_profiles p on p.id=o.provider_id
 where o.is_active and o.publication_status='published' and p.is_active and p.verification_status='verified'and(p_provider_kind is null or p.provider_kind=p_provider_kind)and(p_min_price is null or o.price_amount_tzs is null or o.price_amount_tzs>=p_min_price)and(p_max_price is null or o.price_amount_tzs is null or o.price_amount_tzs<=p_max_price)and(p_location_id is null or exists(select 1 from public.event_service_areas a where a.profile_id=p.id and a.location_id=p_location_id))and(nullif(trim(p_search),'') is null or to_tsvector('simple',coalesce(o.title,'')||' '||coalesce(o.description,'')||' '||coalesce(p.display_name,''))@@plainto_tsquery('simple',trim(p_search)))
 order by case when p_sort='price_low' then o.price_amount_tzs end asc nulls last,case when p_sort='price_high' then o.price_amount_tzs end desc nulls last,case when p_sort='newest' then o.created_at end desc,o.created_at desc limit least(greatest(p_limit,1),50) offset greatest(p_offset,0)
$$;

create or replace function public.create_individual_event_booking(p_kind text,p_equipment_id uuid,p_offering_id uuid,p_start_at timestamptz,p_end_at timestamptz,p_quantity integer default null,p_message text default null)
returns public.event_individual_bookings language plpgsql security definer set search_path=public as $$declare type_id uuid;p public.event_plans;i public.event_plan_items;r public.event_individual_bookings;pricing text;provider_user uuid;begin
 if auth.uid() is null then raise exception 'Authentication required';end if;if p_end_at<=p_start_at then raise exception 'Booking end must be after start';end if;if p_kind not in('equipment','service') then raise exception 'Invalid booking kind';end if;
 select id into type_id from public.event_types where slug='individual-booking';
 if p_kind='equipment' then if p_quantity is null or p_quantity<=0 then raise exception 'Positive quantity required';end if;if not exists(select 1 from public.event_equipment_items where id=p_equipment_id and verification_status='verified' and publication_status='published' and is_active)then raise exception 'Equipment is not publicly bookable';end if;pricing:='fixed';
 else if not exists(select 1 from public.event_service_offerings o join public.event_service_profiles s on s.id=o.provider_id where o.id=p_offering_id and o.publication_status='published' and o.is_active and s.verification_status='verified' and s.is_active)then raise exception 'Service is not publicly bookable';end if;select case when pricing_mode='custom_quote'then'custom_quote'else'fixed'end into pricing from public.event_service_offerings where id=p_offering_id;end if;
 insert into public.event_plans(customer_id,event_type_id,title,event_period,attendance,status,required_component_count)values(auth.uid(),type_id,'Individual Events booking',tstzrange(p_start_at,p_end_at,'[)'),1,'provider_review',1)returning * into p;
 insert into public.event_plan_items(plan_id,item_kind,equipment_id,offering_id,requested_quantity,is_required,requirements)values(p.id,p_kind,case when p_kind='equipment'then p_equipment_id end,case when p_kind='service'then p_offering_id end,case when p_kind='equipment'then p_quantity end,true,nullif(trim(p_message),''))returning * into i;
 insert into public.event_individual_bookings(customer_id,plan_id,plan_item_id,booking_kind,requested_period,requested_quantity,pricing_mode,customer_message)values(auth.uid(),p.id,i.id,p_kind,tstzrange(p_start_at,p_end_at,'[)'),case when p_kind='equipment'then p_quantity end,pricing,nullif(trim(p_message),''))returning * into r;
 if p_kind='equipment'then select op.profile_id into provider_user from public.event_equipment_items e join public.owner_profiles op on op.id=e.owner_id where e.id=p_equipment_id;else select sp.profile_id into provider_user from public.event_service_offerings o join public.event_service_profiles sp on sp.id=o.provider_id where o.id=p_offering_id;end if;
 if provider_user is not null then insert into public.notifications(user_id,type,title,body,payload)values(provider_user,'announcement','New Events booking request','A customer is waiting for your availability response.',jsonb_build_object('eventType','individual_event_request','individualBookingId',r.id,'eventPlanId',p.id,'route','manage/events'));end if;return r;end$$;

create or replace function public.respond_individual_event_booking(p_booking_id uuid,p_approve boolean,p_response text default null)
returns public.event_individual_bookings language plpgsql security definer set search_path=public as $$declare r public.event_individual_bookings;i public.event_plan_items;authorized boolean:=false;begin select * into r from public.event_individual_bookings where id=p_booking_id for update;select * into i from public.event_plan_items where id=r.plan_item_id;if r.id is null or r.status<>'requested'then raise exception 'Booking is not awaiting response';end if;
 if i.item_kind='equipment'then select exists(select 1 from public.event_equipment_items e where e.id=i.equipment_id and e.owner_id=public.current_owner_id())into authorized;else select exists(select 1 from public.event_service_offerings o join public.event_service_profiles s on s.id=o.provider_id where o.id=i.offering_id and s.profile_id=auth.uid())into authorized;end if;if not authorized and not public.is_admin()then raise exception 'Provider access required';end if;
 if p_approve then if i.item_kind='equipment'then perform public.confirm_event_equipment_item(i.id,1440);else perform public.confirm_event_service_item(i.id,60,1440);end if;update public.event_individual_bookings set status='provider_approved',provider_response=nullif(trim(p_response),''),provider_responded_at=now(),updated_at=now()where id=r.id returning * into r;else update public.event_plan_items set status='provider_declined'where id=i.id;update public.event_individual_bookings set status='provider_declined',provider_response=nullif(trim(p_response),''),provider_responded_at=now(),updated_at=now()where id=r.id returning * into r;end if;insert into public.notifications(user_id,type,title,body,payload)values(r.customer_id,'announcement',case when p_approve then'Events booking approved'else'Events booking declined'end,case when p_approve then'Your provider approved the request and will prepare a quotation.'else'Your provider could not accept this request.'end,jsonb_build_object('eventType','individual_event_response','individualBookingId',r.id,'route','account/events'));return r;end$$;

create or replace function public.send_individual_booking_quote(p_booking_id uuid,p_amount_tzs numeric,p_terms text,p_expires_at timestamptz)
returns public.event_individual_bookings language plpgsql security definer set search_path=public as $$declare r public.event_individual_bookings;i public.event_plan_items;authorized boolean:=false;q public.event_quote_revisions;customer uuid;begin select * into r from public.event_individual_bookings where id=p_booking_id for update;select * into i from public.event_plan_items where id=r.plan_item_id;if r.status<>'provider_approved'or p_amount_tzs<0 or p_expires_at<=now()then raise exception 'Approved booking, valid amount and future expiry required';end if;
 if i.item_kind='equipment'then select exists(select 1 from public.event_equipment_items e where e.id=i.equipment_id and e.owner_id=public.current_owner_id())into authorized;else select exists(select 1 from public.event_service_offerings o join public.event_service_profiles s on s.id=o.provider_id where o.id=i.offering_id and s.profile_id=auth.uid())into authorized;end if;if not authorized and not public.has_admin_permission('events.quotes')then raise exception 'Provider access required';end if;
 select customer_id into customer from public.event_plans where id=r.plan_id;insert into public.event_quote_revisions(plan_id,revision,subtotal_tzs,additional_costs_tzs,status,expires_at,created_by)values(r.plan_id,coalesce((select max(revision)+1 from public.event_quote_revisions where plan_id=r.plan_id),1),p_amount_tzs,0,'sent',p_expires_at,auth.uid())returning * into q;insert into public.event_quote_items(quote_revision_id,plan_item_id,description,quantity,unit_price_tzs)values(q.id,i.id,trim(p_terms),coalesce(r.requested_quantity,1),p_amount_tzs/coalesce(r.requested_quantity,1));update public.event_individual_bookings set quoted_amount_tzs=p_amount_tzs,status='quote_sent',updated_at=now()where id=r.id returning * into r;insert into public.notifications(user_id,type,title,body,payload)values(customer,'announcement','Individual event quote ready','Your booking quotation is ready to review.',jsonb_build_object('eventType','individual_event_quote','individualBookingId',r.id,'eventPlanId',r.plan_id,'route','account/events'));return r;end$$;

create or replace function public.sync_individual_booking_after_quote()returns trigger language plpgsql security definer set search_path=public as $$begin if new.status='accepted'and old.status is distinct from new.status then update public.event_individual_bookings set status='quote_accepted',updated_at=now()where plan_id=new.plan_id and status='quote_sent';end if;return new;end$$;
create trigger sync_individual_booking_after_quote after update of status on public.event_quote_revisions for each row execute function public.sync_individual_booking_after_quote();
create or replace function public.sync_individual_booking_after_agreement()returns trigger language plpgsql security definer set search_path=public as $$begin if new.status='sent'and(TG_OP='INSERT'or old.status is distinct from new.status)then update public.event_individual_bookings set status='agreement_sent',updated_at=now()where plan_id=new.plan_id and status='quote_accepted';elsif new.status='accepted'and(TG_OP='INSERT'or old.status is distinct from new.status)then update public.event_individual_bookings set status='confirmed',updated_at=now()where plan_id=new.plan_id;end if;return new;end$$;
create trigger sync_individual_booking_after_agreement after insert or update of status on public.event_agreements for each row execute function public.sync_individual_booking_after_agreement();

revoke all on function public.search_public_event_equipment(text,uuid,uuid,timestamptz,timestamptz,numeric,numeric,text,integer,integer),public.search_public_event_services(text,text,uuid,timestamptz,timestamptz,numeric,numeric,text,integer,integer) from public;
grant execute on function public.search_public_event_equipment(text,uuid,uuid,timestamptz,timestamptz,numeric,numeric,text,integer,integer),public.search_public_event_services(text,text,uuid,timestamptz,timestamptz,numeric,numeric,text,integer,integer) to anon,authenticated;
revoke all on function public.create_individual_event_booking(text,uuid,uuid,timestamptz,timestamptz,integer,text),public.respond_individual_event_booking(uuid,boolean,text),public.send_individual_booking_quote(uuid,numeric,text,timestamptz) from public;
grant execute on function public.create_individual_event_booking(text,uuid,uuid,timestamptz,timestamptz,integer,text),public.respond_individual_event_booking(uuid,boolean,text),public.send_individual_booking_quote(uuid,numeric,text,timestamptz) to authenticated;
